<?php
$escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
$type = $customer->customerType === 'persona_moral' ? 'Persona moral' : 'Persona física';
$customerUrl = $baseUrl . '/admin/clientes';
?>
<section class="section">
    <nav class="breadcrumbs" aria-label="Navegación"><a href="<?php echo $customerUrl; ?>">Clientes</a><span>/</span><span><?php echo $escape($customer->name); ?></span></nav>
    <header class="admin-header"><div><h1><?php echo $escape($customer->name); ?></h1><p>Historial de tickets asociados al cliente.</p></div><div class="ticket-header-actions"><a href="<?php echo $baseUrl; ?>/admin/clientes/<?php echo (int) $customer->id; ?>/editar" class="btn">Editar cliente</a><a href="<?php echo $baseUrl; ?>/admin/tickets/nuevo/cliente/<?php echo (int) $customer->id; ?>" class="btn">Nuevo ticket</a><a href="<?php echo $baseUrl; ?>/admin/tickets?customer=<?php echo urlencode($ticketFilter); ?>" class="btn">Filtrar en tickets</a><a href="<?php echo $customerUrl; ?>" class="btn btn--secondary">Volver</a></div></header>
    <div class="ticket-toolbar"><div class="ticket-results-summary"><strong><?php echo count($tickets); ?></strong> ticket<?php echo count($tickets) === 1 ? '' : 's'; ?> asociado<?php echo count($tickets) === 1 ? '' : 's'; ?></div></div>
    <div class="ticket-detail-grid"><main class="card panel-card ticket-detail-main"><section class="ticket-section"><div class="ticket-section__eyebrow">Cliente</div><h2 class="ticket-section__title">Datos de contacto</h2><div class="ticket-summary-grid"><div class="ticket-kv"><span class="ticket-kv__label">Nombre</span><strong class="ticket-kv__value"><?php echo $escape($customer->name); ?></strong></div><div class="ticket-kv"><span class="ticket-kv__label">Tipo</span><strong class="ticket-kv__value"><?php echo $escape($type); ?></strong></div><div class="ticket-kv"><span class="ticket-kv__label">Razón social</span><strong class="ticket-kv__value"><?php echo $escape($customer->businessName ?: 'No proporcionada'); ?></strong></div><div class="ticket-kv"><span class="ticket-kv__label">Teléfono</span><strong class="ticket-kv__value"><?php echo $escape($customer->phone ?: 'No proporcionado'); ?></strong></div><div class="ticket-kv ticket-kv--wide"><span class="ticket-kv__label">Correo electrónico</span><strong class="ticket-kv__value"><?php echo $customer->email ? '<a href="mailto:' . $escape($customer->email) . '">' . $escape($customer->email) . '</a>' : 'No proporcionado'; ?></strong></div></div></section></main><aside class="ticket-detail-sidebar"><div class="card panel-card"><div class="ticket-section__eyebrow">Resumen</div><h2 class="ticket-section__title">Actividad</h2><div class="ticket-kv"><span class="ticket-kv__label">Tickets registrados</span><strong class="ticket-kv__value"><?php echo count($tickets); ?></strong></div></div></aside></div>
    <section class="ticket-section-card"><div class="ticket-section-card__header"><div><div class="ticket-section__eyebrow">Historial</div><h2 class="ticket-section__title">Tickets del cliente</h2></div></div><div class="table-wrapper"><table class="table table--tickets"><thead><tr><th>Ticket</th><th>Estado</th><th>Origen</th><th>Tipo</th><th>Contexto</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><?php if (!$tickets): ?><tr><td colspan="7">Este cliente aún no tiene tickets registrados.</td></tr><?php else: ?><?php foreach ($tickets as $ticket): ?><tr><td><a class="ticket-primary-link" href="<?php echo $baseUrl; ?>/admin/tickets/<?php echo (int) $ticket['id']; ?>">#<?php echo (int) $ticket['id']; ?></a></td><td><span class="ticket-status ticket-status--<?php echo $escape(strtolower(str_replace(' ', '-', $ticket['status']))); ?>"><span class="ticket-status__dot"></span><?php echo $escape($ticket['status']); ?></span></td><td><?php echo $escape($ticket['origin_type'] === 'promotion' ? 'Promoción' : ($ticket['origin_type'] === 'product' ? 'Producto' : ($ticket['origin_type'] === 'admin' ? 'Admin' : 'Contacto'))); ?></td><td><?php echo $escape($ticket['consultation_type']); ?></td><td><?php echo $escape($ticket['context_label'] ?: 'Sin contexto adicional'); ?></td><td><?php echo $escape(date('d/m/Y H:i', strtotime($ticket['created_at']))); ?></td><td><a class="table__action" href="<?php echo $baseUrl; ?>/admin/tickets/<?php echo (int) $ticket['id']; ?>">Ver ticket</a></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></section>
</section>
